/* Private member tools. Drafts live server-side; no personal data in persistent browser storage. */
window.FMZMembers=(()=>{
 'use strict';const M=FMZMembersModel,esc=s=>escapeHTML(String(s??'')),uid=()=>crypto.randomUUID();let epoch=0,dialog=null,bootstrap=null,wizard=null,profile=null,profileTab="overview",profileRequest=0,timer=null,searchTimer=null,searchSeq=0,busy=false,saveQueue=Promise.resolve();const urls=new Set(),requests=new Map();
 function freezeControls(on){dialog?.querySelectorAll('input,textarea,select,button').forEach(el=>{if(on){if(el.dataset.memberDisabled===undefined)el.dataset.memberDisabled=String(el.disabled);el.disabled=true;}else if(el.dataset.memberDisabled!==undefined){el.disabled=el.dataset.memberDisabled==='true';delete el.dataset.memberDisabled;}});}
 const actor=()=>typeof onlineProfile!=='undefined'?onlineProfile:null,trainer=()=>actor()?.role==='trainer';
 function guard(e=epoch){if(e!==epoch||!actor())throw Error('Sessie gewijzigd. Meld je opnieuw aan.');}
 async function read(action,payload={}){const generation=epoch;guard(generation);const {data,error}=await supabaseClient.rpc('fmz_members_read',{action,payload});guard(generation);if(error)throw Error(error.code==='28000'?'Sessie verlopen. Meld je opnieuw aan.':'Ledeninformatie niet beschikbaar. Probeer opnieuw.');return data;}
 async function command(action,payload){const generation=epoch,key=JSON.stringify([action,payload]);guard(generation);let id=requests.get(key);if(!id){id=uid();requests.set(key,id);}const {data,error}=await supabaseClient.rpc('fmz_members_command',{action,payload,request_id:id});guard(generation);if(error){if(/^(PT409|22|23|42|P0001|28000)/.test(error.code||''))requests.delete(key);throw Object.assign(Error(error.message||'Niet opgeslagen — probeer opnieuw.'),{code:error.code});}requests.delete(key);return data;}
 function message(text,error=false){const out=dialog?.querySelector('[data-members-message]');if(out){out.textContent=text;out.classList.toggle('error',error);}}
 function close(force=false){if(busy&&!force)return false;if(!force&&wizard?.dirty&&!confirm('Er is nog niet-opgeslagen invoer. Teruggaan en dit tabbladconcept sluiten?'))return false;clearTimeout(timer);window.OwnerTestCamera?.cancel();window.OwnerTestMemberViews?.unmount();document.getElementById('clients')?.classList.remove('members-profile-active');dialog?.remove();dialog=null;wizard=null;profile=null;profileRequest++;for(const url of urls)URL.revokeObjectURL(url);urls.clear();return true;}
 function shell(title,fullProfile=false){if(wizard?.dirty&&!confirm('Dit concept bevat nog niet-opgeslagen invoer. Deze invoer verwerpen en een ander onderdeel openen?'))throw Error('Bewaar eerst het open concept.');close(true);dialog=document.createElement(fullProfile?'section':'dialog');dialog.className='members-dialog'+(fullProfile?' members-profile-page':'');dialog.innerHTML=`<header><h2 tabindex="-1">${esc(title)}</h2><button type="button" class="secondary-btn" data-members-close>${fullProfile?'Terug naar leden':'Sluiten'}</button></header><div data-members-body></div><p class="members-message" data-members-message role="status" aria-live="polite"></p>`;dialog.querySelector('[data-members-close]').onclick=()=>{if(close()&&fullProfile){state.ui.selectedClientId=null;window.OwnerTestMemberViews?.clear?.();}};dialog.addEventListener('cancel',e=>{e.preventDefault();close();});if(fullProfile){const host=document.getElementById('clients');host.classList.add('members-profile-active');host.append(dialog);}else{document.body.append(dialog);dialog.showModal();}dialog.querySelector('h2').focus();return dialog.querySelector('[data-members-body]');}
 const button=(label,action,kind='secondary-btn')=>`<button type="button" class="${kind}" data-member-action="${action}">${esc(label)}</button>`;
 const field=(key,label,value='',type='text',required=false)=>`<label class="field"><span>${esc(label)}${required?' *':''}</span><input name="${key}" type="${type}" value="${esc(value)}" aria-describedby="member-error-${key}" aria-invalid="false" ${required?'required':''} ${type==='tel'?'inputmode="tel"':''} autocomplete="off"><small id="member-error-${key}" class="members-field-error" data-error="${key}"></small></label>`;
 const area=(key,label,value='')=>`<label class="field full"><span>${esc(label)}</span><textarea name="${key}" rows="3" aria-describedby="member-error-${key}" aria-invalid="false">${esc(value)}</textarea><small id="member-error-${key}" class="members-field-error" data-error="${key}"></small></label>`;
 function showErrors(errors){dialog.querySelectorAll('[data-error]').forEach(out=>{const key=out.dataset.error;out.textContent=errors[key]||'';dialog.querySelector(`[name="${key}"]`)?.setAttribute('aria-invalid',String(Boolean(errors[key])));});if(Object.keys(errors).length){dialog.querySelector(`[name="${Object.keys(errors)[0]}"]`)?.focus();return true;}return false;}
 function paymentSummary(value){return `<p>Eerste periode: ${esc(value.firstPeriodStart)} t/m ${esc(value.firstPeriodEnd)}</p><p>Totaal: <strong>${M.money(value.baseCents)}</strong> inclusief btw.</p><p>Eerstvolgende vierwekelijkse factuurdatum: ${esc(value.firstPeriodEnd)}</p>`;}
 async function load(){bootstrap=await read('bootstrap');return bootstrap;}
 function packageCard(v){const p=v.snapshot,duo=p.mode==='duo';return `<strong>${esc(p.label.replace(/^Personal training/i,'Personal Training'))}</strong><span class="members-package-price">${M.money(p.cents)} <small>per vier weken</small></span><span>${p.sessions} ${duo?'gezamenlijke trainingen':'trainingen'} per vier weken</span>${duo?`<span>${M.money(p.cents/2)} per persoon</span>`:''}<small>${M.money(Math.round(p.cents/p.sessions/(duo?2:1)))} per training${duo?' per persoon':''}</small>`;}
 async function openEnrollment(id){if(busy||!trainer())return;const root=shell('Nieuw lid inschrijven');root.textContent='Pakketten en concepten laden…';try{await load();if(!dialog)return;const saved=bootstrap.drafts.find(d=>d.id===id),catalog=M.enrollmentCatalog(bootstrap.catalog);wizard={draft:saved||{id:uid(),version:0,data:{person:{country:'Nederland',startDate:todayISO(),marketing:false},payment:{}},catalog_id:catalog[0]?.id},step:0,dirty:false,revision:0,signature:saved?.data?.signing?.signature||[],signer:saved?.data?.signing?.signer||'',confirmed:false};wizard.priceReview=M.enrollmentPriceNeedsReview(saved?.data?.payment)||(!saved?.snapshot?.owner_test_cycle&&M.enrollmentPriceNeedsReview(saved?.snapshot?.payment))||Boolean(saved&&!catalog.some(v=>v.id===saved.catalog_id));if(saved?.status==='review'&&!wizard.priceReview){wizard.signature=saved.snapshot.signature;wizard.signer=saved.snapshot.signer;wizard.confirmed=true;wizard.step=3;}drawWizard();}catch(e){message(e.message,true);}}
 async function cleanupDraftFiles(assets){const generation=epoch;for(const asset of assets.slice(0,100)){guard(generation);const {data,error}=await supabaseClient.functions.invoke('member-assets',{body:{id:asset.id,action:'delete_draft'}});guard(generation);if(error||!data?.ok)throw Error('Concept verwijderd. Bestandsopruiming nog niet bevestigd; kies Opnieuw opruimen.');}}
 async function openDrafts(){const root=shell('Inschrijfconcepten');root.textContent='Concepten laden…';try{await load();root.innerHTML=`<p>Concepten zijn alleen zichtbaar voor jouw bevoegde traineraccount. Er is nog geen lid of betaalafspraak aangemaakt.</p><div class="members-results">${bootstrap.drafts.map(d=>`<article><strong>${esc(M.name(d.data.person||{})||'Naam nog invullen')}</strong><span>Bijgewerkt ${esc(new Date(d.updated_at).toLocaleString('nl-NL'))}</span><button type="button" class="primary-btn" data-draft-open="${d.id}">Hervatten</button><button type="button" class="secondary-btn" data-draft-delete="${d.id}">Ongebruikt concept verwijderen</button></article>`).join('')||'<p>Geen open concepten.</p>'}</div>${bootstrap.cleanup?.length?`<section><h3>Bestandsopruiming afronden</h3><p>${bootstrap.cleanup.length} ingetrokken conceptbestand(en) wachten op bevestigde verwijdering. Definitieve overeenkomsten blijven behouden.</p><button type="button" class="secondary-btn" data-draft-cleanup>Opnieuw opruimen</button></section>`:''}`;
  root.querySelectorAll('[data-draft-open]').forEach(b=>b.onclick=()=>openEnrollment(b.dataset.draftOpen));
  const run=async(draft)=>{if(busy)return;const generation=epoch;if(draft&&!confirm('Dit ongebruikte concept, de conceptgegevens en eventuele concept-PDF definitief verwijderen? Er wordt geen lid of definitieve overeenkomst verwijderd.'))return;busy=true;freezeControls(true);try{if(draft)await command('discard_draft',{id:draft.id,expected_version:draft.version});const fresh=await load();await cleanupDraftFiles((fresh.cleanup||[]).filter(a=>!draft||a.draft_id===draft.id));guard(generation);await openDrafts();message(draft?'Ongebruikt concept en bijbehorende bestanden verwijderd.':'Ingetrokken conceptbestanden zijn verwijderd.');}catch(e){if(generation===epoch){await openDrafts();message(e.message,true);}}finally{if(generation===epoch){busy=false;freezeControls(false);}}};
  root.querySelectorAll('[data-draft-delete]').forEach(b=>b.onclick=()=>run(bootstrap.drafts.find(d=>d.id===b.dataset.draftDelete)));root.querySelector('[data-draft-cleanup]')?.addEventListener('click',()=>run(null));
 }catch(e){message(e.message,true);}}
 function dirty(){if(!wizard)return;wizard.dirty=true;wizard.revision++;wizard.confirmed=false;wizard.draft.snapshot=null;wizard.asset=null;wizard.pdf=null;wizard.fileId=null;clearTimeout(timer);timer=setTimeout(()=>saveDraft().catch(e=>message(e.message,true)),650);message('Nog niet opgeslagen');}
 async function saveDraft(){if(!wizard?.dirty)return;clearTimeout(timer);const target=wizard;const task=async()=>{while(wizard===target&&target.dirty){target.pending||={revision:target.revision,payload:{id:target.draft.id,expected_version:target.draft.version,catalog_id:target.draft.catalog_id,data:structuredClone(target.draft.data)}};const revision=target.pending.revision;message('Concept opslaan…');let result;try{result=await command('save_draft',target.pending.payload);}catch(e){if(e.code&&/^(PT409|22|23|42|P0001|28000)/.test(e.code))target.pending=null;throw e;}if(wizard!==target)return;target.pending=null;target.draft={...result,data:target.draft.data};if(target.revision===revision){target.dirty=false;message('Concept opgeslagen');}else message('Nieuwere invoer nog niet opgeslagen');}};saveQueue=saveQueue.catch(()=>{}).then(task);return saveQueue;}
 function selectedPackage(){return bootstrap.catalog.find(v=>v.id===wizard?.draft.catalog_id);}
 function duoFields(person,primary){const h=M.addressParts(person.houseNumber);return `<fieldset class="members-duo-fields"><legend>Tweede deelnemer</legend><p>${esc(M.name(primary)||'Het eerste lid')} is het hoofdcontractlid. Vul een tweede nieuw fictief lid in voor dezelfde duo-overeenkomst.</p>${field('duo-fullName','Volledige naam',M.name(person),'text',true)}${field('duo-email','E-mailadres',person.email,'email',true)}${field('duo-phone','Telefoonnummer',person.phone,'tel',true)}${field('duo-birthDate','Geboortedatum',person.birthDate,'date',true)}<h4>Adres tweede deelnemer</h4><button type="button" class="secondary-btn" data-duo-address-copy>Hetzelfde adres gebruiken</button>${field('duo-street','Straat',person.street,'text',true)}${field('duo-houseNumber','Huisnummer',h.number,'text',true)}${field('duo-houseAddition','Toevoeging',h.addition)}${field('duo-postalCode','Postcode',person.postalCode,'text',true)}${field('duo-city','Plaats',person.city,'text',true)}${field('duo-country','Land',person.country||'Nederland','text',true)}<p>Startdatum is voor beide deelnemers ${esc(primary.startDate||'de gekozen startdatum')}. Bestaande personen worden niet opnieuw aangemaakt.</p></fieldset>`;}
 function drawWizard(){if(!wizard||!dialog)return;const w=wizard,root=dialog.querySelector('[data-members-body]'),person=w.draft.data.person||{},cat=selectedPackage(),p=cat?.snapshot;let body='';
  if(w.step===0)body=`<h3>Kies je begeleiding</h3>${w.priceReview?'<p class="members-warning" role="alert">Dit oudere concept bevat een ander pakket of een prijsafwijking. Kies bewust opnieuw een pakket om die afwijking te verwijderen. De catalogusprijs geldt daarna voor de hele periode. Er wordt niets stilzwijgend gewijzigd.</p>':''}${[['Personal training individueel',M.individualCatalog(bootstrap.catalog)],['Duo personal training',M.duoCatalog(bootstrap.catalog)]].map(([heading,catalog])=>`<section class="members-package-group"><h4>${heading}</h4><div class="members-packages">${catalog.map(v=>`<article class="members-package" ${v.id===w.draft.catalog_id?'data-selected="true"':''}>${packageCard(v)}<button type="button" class="${v.id===w.draft.catalog_id?'primary-btn':'secondary-btn'}" data-package="${v.id}" aria-pressed="${v.id===w.draft.catalog_id}">Kiezen</button></article>`).join('')||'<p>Geen actieve pakketten in deze groep.</p>'}</div></section>`).join('')}`;
  if(w.step===1){const house=M.addressParts(person.houseNumber);body=`<p>Velden met * zijn nodig voor de overeenkomst. Begeleiding en aanvullende gegevens zijn vrijwillig.</p><form class="members-person-column" data-person novalidate><h3>Persoonsgegevens</h3>${field('fullName','Volledige naam',M.name(person),'text',true)}${field('email','E-mailadres',person.email,'email',true)}${field('phone','Telefoonnummer',person.phone,'tel',true)}${field('birthDate','Geboortedatum',person.birthDate,'date',true)}${field('startDate','Startdatum',person.startDate,'date',true)}<h3>Adres</h3>${field('street','Straat',person.street,'text',true)}${field('houseNumber','Huisnummer',house.number,'text',true)}${field('houseAddition','Toevoeging (optioneel)',house.addition)}${field('postalCode','Postcode',person.postalCode,'text',true)}${field('city','Plaats',person.city,'text',true)}${field('country','Land',person.country,'text',true)}<h3>Doelen en begeleiding</h3>${area('goal','Hoofddoel',person.goal)}${area('experience','Ervaring',person.experience)}${area('preferences','Gewenste begeleiding',person.preferences)}${area('additionalGoals','Aanvullende doelen',person.additionalGoals)}${area('injuries','Relevante blessures, klachten of beperkingen (vrijwillig)',person.injuries)}${area('trainerNote','Aanvullende informatie — alleen voor bevoegde trainers',person.trainerNote)}<label class="members-check"><input type="checkbox" name="healthConsent" ${w.draft.data.healthConsent?'checked':''}>Afzonderlijke vrijwillige toestemming oefenen — alleen een lokaal testkeuzemoment. Dit is geen echte gezondheidsregistratie of juridische toestemming.</label>${p.mode==='duo'?duoFields(w.draft.data.duoPerson||{},person):''}<details><summary>Noodcontact (optioneel)</summary>${field('emergencyName','Naam',person.emergencyName)}${field('emergencyRelation','Relatie',person.emergencyRelation)}${field('emergencyPhone','Telefoonnummer noodcontact',person.emergencyPhone,'tel')}</details><label class="members-check"><input type="checkbox" name="marketing" ${person.marketing?'checked':''}>Ik geef apart toestemming voor marketing. Dit is niet nodig voor de begeleiding.</label><p>Privacytekst: <strong>CONCEPT — NIET VOOR ECHTE LEDEN</strong>. Gezondheidsinformatie helpt om begeleiding af te stemmen, is vrijwillig en vraagt aparte toestemming.</p><div data-duplicates></div></form>`;}
  if(w.step===2){const pay=M.payment(p,person.startDate,{}).value;body=`<h3>Kostenoverzicht</h3><div class="members-summary members-cost-summary"><strong>${esc(p.label)}</strong>${p.mode==='duo'?`<p>Hoofdcontractlid: ${esc(M.name(person))}<br>Tweede deelnemer: ${esc(M.name(w.draft.data.duoPerson||{}))}</p><p>Beide personen worden aan één duo-overeenkomst gekoppeld.</p>`:''}<dl class="members-details"><dt>Trainingen per vier weken</dt><dd>${p.sessions}</dd><dt>Prijs per ${p.mode==='duo'?'gezamenlijke training':'training'}</dt><dd>${M.money(Math.round(p.cents/p.sessions))}</dd>${p.mode==='duo'?`<dt>Per persoon per vier weken</dt><dd>${M.money(p.cents/2)}</dd><dt>Per training per persoon</dt><dd>${M.money(Math.round(p.cents/p.sessions/2))}</dd>`:''}<dt>Totaal per vier weken</dt><dd><strong>${M.money(p.cents)}</strong> inclusief btw</dd><dt>Startdatum</dt><dd>${esc(person.startDate)}</dd><dt>Eerste periode</dt><dd>${esc(pay.firstPeriodStart)} t/m ${esc(pay.firstPeriodEnd)}</dd><dt>Verwachte handmatige factuurdatum</dt><dd>${esc(pay.firstPeriodEnd)}</dd></dl></div>`;}
  if(w.step===2&&window.OwnerTestBillingUI){const summary=OwnerTestBillingUI.costSummary(p,person,w.draft);if(summary)body='<h3>Kostenoverzicht</h3>'+summary;}
  if(w.step===3){const terms=bootstrap.terms;body=`<h3>Controleren en ondertekenen</h3><div class="members-summary"><strong>${esc(M.name(person))}</strong><p>${esc(person.email)} · ${esc(person.phone)}</p><p>${esc([person.street+' '+person.houseNumber,person.postalCode+' '+person.city,person.country].join(', '))}</p><p>Geboortedatum ${esc(person.birthDate)} · start ${esc(person.startDate)}</p>${cat?packageCard(cat):''}${p.mode==='duo'?`<p><strong>Hoofdcontractlid:</strong> ${esc(M.name(person))}<br><strong>Tweede deelnemer:</strong> ${esc(M.name(w.draft.data.duoPerson||{}))} · ${esc(w.draft.data.duoPerson?.email)}</p><p>Eén gedeelde duo-overeenkomst; de hoofdcontractant ondertekent.</p>`:''}${window.OwnerTestBillingUI?.costSummary(p,person,w.draft)||paymentSummary(M.payment(p,person.startDate,{}).value)}</div>${terms?`<div class="members-terms"><h4>Belangrijkste afspraken</h4>${Object.entries(terms.summary).map(([k,v])=>`<p><strong>${esc(({notice:'Opzegtermijn',lateCancellation:'Afzeggen'}[k]||k))}:</strong> ${esc(v)}</p>`).join('')}<details><summary>Volledige algemene voorwaarden — ${esc(terms.version)}</summary><pre>${esc(terms.terms_text)}</pre></details><details><summary>Volledige privacyvoorwaarden — ${esc(terms.version)}</summary><pre>${esc(terms.privacy_text)}</pre></details></div>`:'<div class="members-warning" role="alert">Ondertekenen is nog niet beschikbaar: de volledige geldende algemene voorwaarden en privacyvoorwaarden zijn nog niet bevestigd. Je kunt dit concept veilig bewaren.</div>'}<label class="field"><span>Naam ondertekenaar</span><input data-signer value="${esc(w.signer||M.name(person))}" autocomplete="off"></label><p>Teken met vinger, muis, touchpad of stylus.</p><canvas class="members-signature" data-signature tabindex="0" aria-label="Handtekening tekenen" aria-describedby="signature-keys" role="application"></canvas><p id="signature-keys">Toetsenbord: spatie zet de pen aan of uit. Pijltjestoetsen bewegen de pen; met pen aan teken je een lijn. Escape zet de pen uit. Tab gaat naar de volgende knop.</p><p data-pen-status role="status">Pen uit</p><div class="members-actions">${button('Handtekening wissen','clear-signature')}${button('Opnieuw tekenen','clear-signature')}</div><label class="members-check"><input type="checkbox" data-confirmed ${w.confirmed?'checked':''} ${terms?'':'disabled'}>Ik heb alle gegevens en de volledige voorwaarden bekeken.</label><p>Een lege handtekening kan niet worden bevestigd. De definitieve overeenkomst blijft onveranderlijk.</p>${button('Ondertekend PDF-voorbeeld controleren','preview','primary-btn')}<div data-agreement-preview></div>`;}
  root.innerHTML=`<ol class="members-steps" aria-label="Inschrijfvoortgang">${M.steps.map((s,i)=>`<li ${i===w.step?'aria-current="step"':''}>${i+1}. ${s}</li>`).join('')}</ol><p>Stap ${w.step+1} van 5</p>${body}<nav class="members-actions" aria-label="Inschrijfstappen">${w.step?button('Vorige','previous'):''}${button('Concept opslaan','save')}${w.step<3?button('Volgende','next','primary-btn'):''}${w.step===3&&w.draft.status==='review'&&w.draft.snapshot?button('Inschrijving definitief bevestigen','finalize','primary-btn'):''}</nav>`;
  root.querySelectorAll('[data-member-action]').forEach(b=>b.onclick=()=>wizardAction(b.dataset.memberAction));root.querySelectorAll('[data-package]').forEach(input=>input.onclick=()=>{w.draft.catalog_id=input.dataset.package;w.draft.data.payment={};w.draft.data.duoPerson||={country:'Nederland',startDate:w.draft.data.person.startDate};w.priceReview=false;dirty();drawWizard();});
  const form=root.querySelector('[data-person]');if(form){form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',e=>{const input=e.target;let name=input.name,target=w.draft.data.person;if(name==='healthConsent'){w.draft.data.healthConsent=input.checked;dirty();return;}if(name.startsWith('duo-')){name=name.slice(4);target=w.draft.data.duoPerson||=( {country:'Nederland',startDate:person.startDate});}const prefix=target===w.draft.data.person?'':'duo-';if(name==='fullName')Object.assign(target,M.nameParts(input.value));else if(name==='houseNumber'||name==='houseAddition')target.houseNumber=[form.elements[prefix+'houseNumber'].value,form.elements[prefix+'houseAddition'].value].filter(Boolean).join(' ');else target[name]=input.type==='checkbox'?input.checked:input.value;if(input.name==='startDate'&&w.draft.data.duoPerson)w.draft.data.duoPerson.startDate=input.value;dirty();});form.querySelector('[data-duo-address-copy]')?.addEventListener('click',()=>{const target=w.draft.data.duoPerson||={};for(const k of ['street','houseNumber','postalCode','city','country'])target[k]=w.draft.data.person[k]||'';dirty();drawWizard();});}
  if(form){const health=form.querySelector('[name=injuries]');if(health){health.disabled=true;health.setAttribute('aria-describedby','member-health-gate');health.insertAdjacentHTML('afterend','<small id="member-health-gate">Dit veld blijft in deze eigenaarstest geblokkeerd. De oefencheckbox legt geen gezondheidstoestemming vast. De echte route vraagt accountactivatie, eigen afzonderlijke toestemming en een goedgekeurde privacytekst. Bewaar ook geen medische informatie in vrije notities.</small>');}}
  if(w.step===3){signatureCanvas();root.querySelector('[data-signer]').oninput=e=>{w.signer=e.target.value;w.draft.data.signing={signature:w.signature,signer:w.signer};dirty();root.querySelector('[data-confirmed]').checked=false;};root.querySelector('[data-confirmed]').onchange=e=>w.confirmed=e.target.checked;}
 }
